def factorial_recursive(n):
    """Calcula el factorial de n usando recursión."""
    if not isinstance(n, int) or n < 0:
        raise ValueError("La entrada debe ser un entero no negativo.")

    # Caso base
    if n == 0:
        return 1

    # Paso recursivo
    return n * factorial_recursive(n - 1)

# Ejemplo de uso:
# print(factorial_recursive(5))  # Devuelve 120
# print(factorial_recursive(0))  # Devuelve 1

