def find_duplicates(data_list):
    duplicates = []
    n = len(data_list)
    for i in range(n):
        for j in range(i + 1, n):
            if data_list[i] == data_list[j]:
                if data_list[i] not in duplicates:
                    duplicates.append(data_list[i])
    return duplicates

