def fibonacci_recursive(n):
    """Calcula el número de Fibonacci n utilizando recursión.
    Devuelve 0 para entradas no positivas.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

